<section class="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h1 class="text-2xl font-bold text-slate-900">Data Tagihan</h1><p class="mt-1 text-sm text-slate-500">Riwayat tagihan dan status pembayaran pelanggan.</p></div><?php if (Auth::isAdmin()): ?><a href="<?= e(url('/tagihan/create')) ?>" class="inline-flex items-center justify-center rounded-xl bg-primary px-4 py-3 text-sm font-semibold text-white shadow-lg shadow-blue-900/15 hover:bg-primary-dark">+ Tambah Tagihan</a><?php endif; ?></section>
<section class="rounded-2xl bg-white p-4 shadow-card sm:p-6"><form class="grid gap-3 md:grid-cols-[1fr_180px_auto]" method="get"><div class="relative"><span class="absolute left-3 top-3 text-slate-400">⌕</span><input name="q" value="<?= e($search) ?>" class="form-input pl-9" placeholder="Cari NPA atau nama pelanggan"></div><select name="status" class="form-input"><option value="">Semua pembayaran</option><option value="Lunas" <?= $status === 'Lunas' ? 'selected' : '' ?>>Lunas</option><option value="Belum Lunas" <?= $status === 'Belum Lunas' ? 'selected' : '' ?>>Belum Lunas</option></select><div class="flex gap-2"><button class="rounded-xl bg-primary px-5 py-3 text-sm font-semibold text-white">Cari</button><a href="<?= e(url('/tagihan')) ?>" class="rounded-xl border border-slate-200 px-4 py-3 text-sm font-semibold text-slate-600">Reset</a></div></form><div class="mt-6 overflow-hidden rounded-xl border border-slate-100"><?php if ($data['rows']): ?><div class="table-wrap"><table class="w-full min-w-[940px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-5 py-3">NPA</th><th class="px-5 py-3">Pelanggan</th><th class="px-5 py-3">Periode</th><th class="px-5 py-3">Meter</th><th class="px-5 py-3">Total</th><th class="px-5 py-3">Status</th><th class="px-5 py-3">Tgl. Bayar</th><?php if(Auth::isAdmin()): ?><th class="px-5 py-3 text-right">Aksi</th><?php endif; ?></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($data['rows'] as $row): ?><tr><td class="px-5 py-4 font-mono text-xs font-semibold text-primary"><?= e($row['npa']) ?></td><td class="px-5 py-4"><a class="font-semibold text-slate-800 hover:text-primary" href="<?= e(url('/pelanggan/' . rawurlencode($row['npa']))) ?>"><?= e($row['nama_pelanggan']) ?></a></td><td class="px-5 py-4 text-slate-600"><?= e(formatTanggal($row['periode'])) ?></td><td class="px-5 py-4 text-slate-600"><?= e(($row['meter_awal'] ?? '—') . ' – ' . ($row['meter_akhir'] ?? '—')) ?></td><td class="px-5 py-4 font-semibold text-slate-800"><?= e(formatRupiah($row['total_tagihan'])) ?></td><td class="px-5 py-4"><span class="badge badge-<?= $row['status_bayar'] === 'Lunas' ? 'disetujui' : 'pending' ?>"><?= e($row['status_bayar']) ?></span></td><td class="px-5 py-4 text-slate-600"><?= e(formatTanggal($row['tgl_bayar'])) ?></td><?php if(Auth::isAdmin()): ?><td class="px-5 py-4 text-right"><a class="font-semibold text-primary hover:underline" href="<?= e(url('/tagihan/' . $row['id_tagihan'] . '/edit')) ?>">Ubah</a></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php else: $emptyTitle='Tagihan tidak ditemukan'; $emptyText='Belum ada data yang sesuai dengan pencarian Anda.'; require root_path('app/Views/components/empty-state.php'); endif; ?></div><?php require root_path('app/Views/components/pagination.php'); ?></section>
